    // Function to check if a number is prime
    function isPrime(num) {
        // Numbers less than 2 are not prime
        if (num < 2) return false;

        // Check for divisibility from 2 to square root of the number
        for (let i = 2; i <= Math.sqrt(num); i++) {
            if (num % i === 0) {
                return false;
            }
        }

        return true;
    }

